import { type NextRequest, NextResponse } from 'next/server'
import { createSupabaseClientForApiRoute } from '@/lib/supabase/api-route-client'
import { success, error } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import { resolveUserPropertyAccessOrThrow, AccessDeniedError } from '@/lib/rbac'
import { getPermissionsForRole } from '@/lib/rbac/permissions'
import { resolveStaffPermissions } from '@/lib/rbac/staff-categories'

/**
 * GET /api/v1/me/permissions?propertyId=...
 *
 * Returns the current user's resolved role, categories, and permissions for a property.
 */
export async function GET(request: NextRequest) {
  try {
    const { supabase, user, error: authError } = await createSupabaseClientForApiRoute(request)

    if (authError || !user) {
      return error(ErrorCodes.AUTH_001, request)
    }

    const propertyId = request.nextUrl.searchParams.get('propertyId')?.trim() ?? ''

    if (!propertyId) {
      return error(
        ErrorCodes.VALIDATION_ERROR.code,
        'propertyId query parameter is required',
        ErrorCodes.VALIDATION_ERROR.status,
        request,
      )
    }

    const access = await resolveUserPropertyAccessOrThrow(
      supabase as any,
      propertyId,
      user.id,
      user.user_metadata,
    )

    // Build permission set: role permissions + staff category permissions
    const rolePerms = access.role ? getPermissionsForRole(access.role) : new Set<string>()
    const categoryPerms = access.categories.length > 0
      ? resolveStaffPermissions(access.categories)
      : new Set<string>()
    const allPerms = new Set([...rolePerms, ...categoryPerms])

    const payload = {
        role: access.role,
        rawRole: access.rawRole,
        categories: access.categories,
        permissions: [...allPerms],
        isOwner: access.isOwner,
        isElevated: access.isElevated,
        isPlatformAdmin: access.isPlatformAdmin,
      }

    return NextResponse.json(
      { success: true, data: payload },
      {
        status: 200,
        headers: {
          'Cache-Control': 'private, max-age=30',
        },
      },
    )
  } catch (err: unknown) {
    if (err instanceof AccessDeniedError) {
      return error(
        err.statusCode === 404 ? ErrorCodes.AUTH_003 : ErrorCodes.AUTH_002,
        request,
      )
    }

    const message = err instanceof Error ? err.message : 'Unknown error'
    console.error('[me/permissions] GET error:', err)
    return error(ErrorCodes.INTERNAL_ERROR, request, { message })
  }
}

'use client'

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import type { EffectiveRole } from '@/lib/rbac/roles'
import { roleMeetsMinimum } from '@/lib/rbac/roles'
import type { StaffCategory } from '@/lib/rbac/staff-categories'
import { hasCategory } from '@/lib/rbac/staff-categories'

// ─── Context value ─────────────────────────────────────────────────────────────

export interface PermissionContextValue {
  /** Normalised role, or null if still loading / unauthenticated. */
  role: EffectiveRole | null
  /** Raw role from the database. */
  rawRole: string | null
  /** Staff categories assigned to the user. */
  categories: StaffCategory[]
  /** Set of all permission keys granted to this user. */
  permissions: ReadonlySet<string>
  /** Check if a specific permission is granted. */
  can: (key: string) => boolean
  /** Check if any of the given permissions are granted. */
  canAny: (keys: string[]) => boolean
  /** Check if all of the given permissions are granted. */
  canAll: (keys: string[]) => boolean
  /** Check if user has exactly the given role. */
  isRole: (role: EffectiveRole) => boolean
  /** Check if user's role meets or exceeds the minimum. */
  isAtLeastRole: (minimum: EffectiveRole) => boolean
  /** Check if user has a specific staff category (or 'all'). */
  hasCategory: (cat: StaffCategory) => boolean
  /** Whether the permissions are still being fetched. */
  isLoading: boolean
  /** Error from the API call, if any. */
  error: string | null
  /** Manually trigger a permission refresh. */
  refreshPermissions: () => void
}

// ─── Null context (for unauthenticated / no property) ────────────────────────

const NULL_CONTEXT: PermissionContextValue = {
  role: null,
  rawRole: null,
  categories: [],
  permissions: new Set(),
  can: () => false,
  canAny: () => false,
  canAll: () => false,
  isRole: () => false,
  isAtLeastRole: () => false,
  hasCategory: () => false,
  isLoading: false,
  error: null,
  refreshPermissions: () => {},
}

const PermissionContext = createContext<PermissionContextValue>(NULL_CONTEXT)

// ─── Provider ─────────────────────────────────────────────────────────────────

interface PermissionProviderProps {
  propertyId: string | null | undefined
  children: ReactNode
}

export function PermissionProvider({ propertyId, children }: PermissionProviderProps) {
  const [role, setRole] = useState<EffectiveRole | null>(null)
  const [rawRole, setRawRole] = useState<string | null>(null)
  const [categories, setCategories] = useState<StaffCategory[]>([])
  const [permissions, setPermissions] = useState<ReadonlySet<string>>(new Set())
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Ref to force re-fetch on demand
  const refreshTrigger = useRef(0)

  // Polling timer ref (60s interval)
  const pollingTimerRef = useRef<ReturnType<typeof setInterval> | null>(null)

  const fetchPermissions = useCallback(async () => {
    if (!propertyId) {
      setRole(null)
      setRawRole(null)
      setCategories([])
      setPermissions(new Set())
      setError(null)
      setIsLoading(false)
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const res = await fetch(
        `/api/v1/me/permissions?propertyId=${encodeURIComponent(propertyId)}`,
        { credentials: 'include' },
      )

      if (!res.ok) {
        const body = await res.json().catch(() => null)
        setError(body?.error?.message ?? `Request failed with status ${res.status}`)
        setRole(null)
        setRawRole(null)
        setCategories([])
        setPermissions(new Set())
        return
      }

      const result = await res.json()

      if (!result.success || !result.data) {
        setError('Invalid response from permissions API')
        setRole(null)
        setRawRole(null)
        setCategories([])
        setPermissions(new Set())
        return
      }

      const d = result.data
      setRole(d.role)
      setRawRole(d.rawRole)
      setCategories(d.categories ?? [])
      setPermissions(new Set(d.permissions ?? []))
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch permissions'
      setError(message)
      setRole(null)
      setRawRole(null)
      setCategories([])
      setPermissions(new Set())
    } finally {
      setIsLoading(false)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps -- refreshTrigger ref read triggers intentional re-fetch
  }, [propertyId, refreshTrigger.current])

  // Re-fetch when propertyId changes, plus 60s polling and window focus refresh
  useEffect(() => {
    // Initial fetch
    void fetchPermissions()

    // Poll every 60 seconds
    pollingTimerRef.current = setInterval(() => {
      void fetchPermissions()
    }, 60_000)

    // Re-fetch on window focus (tab switch)
    const onFocus = () => { void fetchPermissions() }
    window.addEventListener('focus', onFocus)

    return () => {
      if (pollingTimerRef.current) clearInterval(pollingTimerRef.current)
      window.removeEventListener('focus', onFocus)
    }
  }, [fetchPermissions])

  const refreshPermissions = useCallback(() => {
    refreshTrigger.current += 1
    void fetchPermissions()
  }, [fetchPermissions])

  const value = useMemo<PermissionContextValue>(() => ({
    role,
    rawRole,
    categories,
    permissions,
    can: (key: string) => permissions.has(key),
    canAny: (keys: string[]) => keys.some((k) => permissions.has(k)),
    canAll: (keys: string[]) => keys.every((k) => permissions.has(k)),
    isRole: (r: EffectiveRole) => role === r,
    isAtLeastRole: (minimum: EffectiveRole) => role ? roleMeetsMinimum(role, minimum) : false,
    hasCategory: (cat: StaffCategory) => hasCategory(categories, cat),
    isLoading,
    error,
    refreshPermissions,
  }), [role, rawRole, categories, permissions, isLoading, error, refreshPermissions])

  return (
    <PermissionContext.Provider value={value}>
      {children}
    </PermissionContext.Provider>
  )
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function usePermissions(): PermissionContextValue {
  return useContext(PermissionContext)
}

/**
 * Check if an error indicates a 403 access denied response from the API.
 *
 * The RBAC deny() function returns JSON: { success: false, error: { code: 'AUTH_003', message: '...' } }
 * When parsed on the client, we check for:
 * - 403 status code in fetch responses
 * - 'AUTH_003' error code
 * - 'forbidden' or 'access denied' in the message
 */
export function isAccessDeniedError(error: unknown): boolean {
  if (error instanceof Error) {
    const msg = error.message.toLowerCase()
    return (
      msg.includes('403') ||
      msg.includes('auth_003') ||
      msg.includes('forbidden') ||
      msg.includes('access denied') ||
      msg.includes('insufficient role') ||
      msg.includes('permission denied')
    )
  }
  if (typeof error === 'string') {
    const msg = error.toLowerCase()
    return (
      msg.includes('403') ||
      msg.includes('auth_003') ||
      msg.includes('forbidden') ||
      msg.includes('access denied') ||
      msg.includes('insufficient role') ||
      msg.includes('permission denied')
    )
  }
  return false
}

'use client'

import type { ReactNode } from 'react'
import { usePermissions } from '@/hooks/use-permissions'
import type { PermissionKey } from '@/lib/rbac'
import type { EffectiveRole } from '@/lib/rbac/roles'
import type { StaffCategory } from '@/lib/rbac/staff-categories'

interface PermissionGateProps {
  children: ReactNode
  /** Specific permission key required. */
  permission?: PermissionKey
  /** Minimum effective role required. */
  minimumRole?: EffectiveRole
  /** Require at least one of these categories. */
  anyCategory?: StaffCategory[]
  /** Require any of these specific roles. */
  anyOfRoles?: EffectiveRole[]
  /** Rendered when permission check fails. Default: null (hidden). */
  fallback?: ReactNode
}

/**
 * Conditionally renders children based on the current user's permissions.
 *
 * Default behavior: HIDDEN (renders null) when permission check fails.
 * Use `fallback` prop to render a disabled element or message instead.
 */
export function PermissionGate({
  children,
  permission,
  minimumRole,
  anyCategory,
  anyOfRoles,
  fallback = null,
}: PermissionGateProps) {
  const { can, isAtLeastRole, hasCategory, isRole, isLoading } = usePermissions()

  // While loading, show nothing (safe default)
  if (isLoading) return null

  // Check minimum role
  if (minimumRole && !isAtLeastRole(minimumRole)) return <>{fallback}</>

  // Check anyOfRoles
  if (anyOfRoles && !anyOfRoles.some((r) => isRole(r))) return <>{fallback}</>

  // Check permission
  if (permission && !can(permission)) return <>{fallback}</>

  // Check category
  if (anyCategory && anyCategory.length > 0 && !anyCategory.some((c) => hasCategory(c))) {
    return <>{fallback}</>
  }

  return <>{children}</>
}

'use client'

import type { ButtonHTMLAttributes } from 'react'
import { usePermissions } from '@/hooks/use-permissions'
import type { PermissionKey } from '@/lib/rbac'
import type { EffectiveRole } from '@/lib/rbac/roles'
import {
  Button,
  type ButtonProps,
} from '@/components/ui/button'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'

interface PermissionButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Specific permission key required. */
  permission?: PermissionKey
  /** Minimum effective role required. */
  minimumRole?: EffectiveRole
  /**
   * Display mode when permission is missing.
   * - 'hidden' (default): renders null — button is completely hidden.
   * - 'disabled': renders a disabled button with tooltip explaining why.
   */
  mode?: 'hidden' | 'disabled'
  /** Tooltip text shown when mode='disabled' and permission is missing. */
  tooltipText?: string
  /** shadcn Button variant, size, etc. */
  variant?: ButtonProps['variant']
  size?: ButtonProps['size']
  children: React.ReactNode
}

/**
 * A Button that respects the current user's RBAC permissions.
 *
 * Default behavior: HIDDEN when permission check fails (same as PermissionGate).
 * Use `mode="disabled"` to show a disabled button with a tooltip instead.
 */
export function PermissionButton({
  permission,
  minimumRole,
  mode = 'hidden',
  tooltipText = "You don't have permission for this action",
  variant,
  size,
  children,
  ...buttonProps
}: PermissionButtonProps) {
  const { can, isAtLeastRole, isLoading } = usePermissions()

  if (isLoading) return null

  const hasAccess = (!permission || can(permission)) && (!minimumRole || isAtLeastRole(minimumRole))

  if (!hasAccess) {
    if (mode === 'disabled') {
      return (
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <span>
                <Button variant={variant} size={size} disabled {...buttonProps}>
                  {children}
                </Button>
              </span>
            </TooltipTrigger>
            <TooltipContent>
              <p>{tooltipText}</p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )
    }
    return null
  }

  return (
    <Button variant={variant} size={size} {...buttonProps}>
      {children}
    </Button>
  )
}

import { type NextRequest } from 'next/server'
import { createSupabaseClientForApiRoute } from '@/lib/supabase/api-route-client'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { success, error } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import { requirePropertyAccess, isDenied } from '@/lib/rbac'
import { StaffManagementQueries } from '@/lib/dashboard/staff-management-queries'

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string }> },
) {
  try {
    const { propertyId } = await params
    const { supabase, user, error: authError } = await createSupabaseClientForApiRoute(request)

    if (authError || !user) {
      return error(ErrorCodes.AUTH_001, request)
    }

    const access = await requirePropertyAccess(supabase as any, user.id, {
      propertyId,
      minimumRole: 'manager',
    })
    if (isDenied(access)) return access

    const q = new StaffManagementQueries(supabase as any)
    const admin = createServiceRoleClient()
    const staff = await q.listStaffForManagementTable(propertyId, admin)

    return success({ staff }, request)
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    return error(ErrorCodes.INTERNAL_ERROR, request, { message })
  }
}

"use client"

import type React from "react"

import { Suspense, useState, useEffect, useTransition } from "react"
import Link from "next/link"
import Image from "next/image"
import { usePathname, useRouter } from "next/navigation"
import { createClient } from "@/lib/supabase/client"
import { getStaffDeactivationPublicUrl } from "@/lib/dashboard/staff-deactivation-public-url"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Sheet, SheetContent, SheetTrigger, SheetTitle } from "@/components/ui/sheet"
import {
  LayoutDashboard,
  Calendar,
  Tent,
  Users,
  CreditCard,
  Settings,
  Menu,
  LogOut,
  Building2,
  BarChart3,
  Bell,
  Loader2,
  History,
  Wrench,
  ClipboardList,
} from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { PropertyProvider, useProperty } from "@/components/property-context"
import { PropertySwitcher } from "@/components/dashboard/property-switcher"
import { SetupCheckGate } from "@/components/dashboard/setup-check-gate"
import { SetupCompleteToast } from "@/components/dashboard/setup-complete-toast"
import { QuickTourPrompt } from "@/components/dashboard/quick-tour-prompt"
import { PermissionProvider } from "@/hooks/use-permissions"

const NAV_ITEMS = [
  { name: "Overview", path: "", icon: LayoutDashboard },
  { name: "Reservations", path: "/reservations", icon: Calendar },
  { name: "Sites", path: "/sites", icon: Tent },
  { name: "Guests", path: "/guests", icon: Users },
  { name: "Payments", path: "/payments", icon: CreditCard },
  { name: "Analytics", path: "/analytics", icon: BarChart3 },
  { name: "Staff Management", path: "/staff-management", icon: Users },
  { name: "Auditing", path: "/auditing", icon: History },
  { name: "Housekeeping", path: "/housekeeping", icon: ClipboardList },
  { name: "Maintenance", path: "/maintenance", icon: Wrench },
  { name: "Settings", path: "/settings", icon: Settings },
] as const

const OPERATIONS_MODULE_PATHS = new Set<
  (typeof NAV_ITEMS)[number]["path"]
>(["/reservations", "/sites", "/guests", "/payments", "/analytics", "/auditing"])

const COMPANY_DETAILS_UPDATED_EVENT = "company-details-updated"

type CompanyDetailsUpdatedEventDetail = {
  companyId: string
  name: string
  companyLogoUrl: string | null
}

function DashboardLayoutContent({ children }: { children: React.ReactNode }) {
  const pathname = usePathname()
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [companyName, setCompanyName] = useState<string | null>(null)
  const [companyLogoUrl, setCompanyLogoUrl] = useState<string | null>(null)
  const [isCompanyLoading, setIsCompanyLoading] = useState(true)
  const [logoLoadFailed, setLogoLoadFailed] = useState(false)
  const [userDisplayName, setUserDisplayName] = useState<string | null>(null)
  const [userRoleLabel, setUserRoleLabel] = useState<string>("User")
  const [isStaffUserType, setIsStaffUserType] = useState(false)
  const [isUserLoading, setIsUserLoading] = useState(true)
  const [staffManagementNavVisible, setStaffManagementNavVisible] = useState(false)
  const [propertySettingsNavVisible, setPropertySettingsNavVisible] = useState(false)
  const [operationsModulesNavVisible, setOperationsModulesNavVisible] = useState(false)
  const [financialNavVisible, setFinancialNavVisible] = useState(false)
  const [housekeepingNavVisible, setHousekeepingNavVisible] = useState(false)
  const [maintenanceNavVisible, setMaintenanceNavVisible] = useState(false)
  const { selectedProperty, selectedPropertyId, selectProperty, isLoading } = useProperty()
  const companyId = selectedProperty?.companyId ?? null
  const dashboardTitle = isLoading ? "Loading..." : companyName

  const segments = pathname.split("/").filter(Boolean)
  const propertyIdFromUrl = segments[0] === "dashboard" && segments[1] ? segments[1] : null
  const dashboardBase = propertyIdFromUrl ? `/dashboard/${propertyIdFromUrl}` : "/dashboard"

  useEffect(() => {
    if (propertyIdFromUrl && propertyIdFromUrl !== selectedPropertyId) {
      selectProperty(propertyIdFromUrl)
    }
  }, [propertyIdFromUrl, selectedPropertyId, selectProperty])

  useEffect(() => {
    let cancelled = false
    setIsUserLoading(true)

    const query =
      propertyIdFromUrl && propertyIdFromUrl.length > 0
        ? `?propertyId=${encodeURIComponent(propertyIdFromUrl)}`
        : ""

    void (async () => {
      try {
        const response = await fetch(`/api/v1/me/dashboard-layout-context${query}`, {
          credentials: "include",
        })
        const result: {
          success?: boolean
          data?: {
            displayName: string
            roleLabel: string
            isStaffUserType?: boolean
            staffDeactivatedForProperty?: boolean
            staffManagementNavVisible: boolean
            propertySettingsNavVisible: boolean
            operationsModulesNavVisible: boolean
            financialNavVisible?: boolean
            housekeepingNavVisible?: boolean
            maintenanceNavVisible?: boolean
          }
        } = await response.json()

        if (cancelled) return

        if (result.success === true && result.data?.staffDeactivatedForProperty === true) {
          const supabase = createClient()
          await supabase.auth.signOut()
          window.location.replace(getStaffDeactivationPublicUrl())
          return
        }

        if (!response.ok || !result.success || !result.data) {
          setUserDisplayName(null)
          setUserRoleLabel("User")
          setIsStaffUserType(false)
          setStaffManagementNavVisible(false)
          setPropertySettingsNavVisible(false)
          setOperationsModulesNavVisible(false)
          setFinancialNavVisible(false)
          setHousekeepingNavVisible(false)
          setMaintenanceNavVisible(false)
          return
        }

        const d = result.data
        setUserDisplayName(d.displayName)
        setUserRoleLabel(d.roleLabel)
        setIsStaffUserType(d.isStaffUserType ?? false)
        setStaffManagementNavVisible(d.staffManagementNavVisible)
        setPropertySettingsNavVisible(d.propertySettingsNavVisible)
        setOperationsModulesNavVisible(d.operationsModulesNavVisible)
        setFinancialNavVisible(d.financialNavVisible ?? true)
        setHousekeepingNavVisible(d.housekeepingNavVisible ?? false)
        setMaintenanceNavVisible(d.maintenanceNavVisible ?? false)
      } catch {
        if (!cancelled) {
          setUserDisplayName(null)
          setUserRoleLabel("User")
          setIsStaffUserType(false)
          setStaffManagementNavVisible(false)
          setPropertySettingsNavVisible(false)
          setOperationsModulesNavVisible(false)
          setFinancialNavVisible(false)
          setHousekeepingNavVisible(false)
          setMaintenanceNavVisible(false)
        }
      } finally {
        if (!cancelled) {
          setIsUserLoading(false)
        }
      }
    })()

    return () => {
      cancelled = true
    }
  }, [propertyIdFromUrl, pathname])

  useEffect(() => {
    let isCancelled = false

    async function fetchCompanyName() {
      if (!companyId) {
        setCompanyName(null)
        setCompanyLogoUrl(null)
        setIsCompanyLoading(false)
        setLogoLoadFailed(false)
        return
      }

      setIsCompanyLoading(true)
      try {
        const response = await fetch(`/api/v1/companies/${companyId}`)
        const result = await response.json()

        if (!isCancelled && response.ok && result?.success) {
          setCompanyName(result.data?.name ?? null)
          setCompanyLogoUrl(result.data?.companyLogoUrl ?? null)
          setLogoLoadFailed(false)
        } else if (!isCancelled) {
          setCompanyName(null)
          setCompanyLogoUrl(null)
          setLogoLoadFailed(false)
        }
      } catch (error) {
        console.error("Failed to fetch company name:", error)
        if (!isCancelled) {
          setCompanyName(null)
          setCompanyLogoUrl(null)
          setLogoLoadFailed(false)
        }
      } finally {
        if (!isCancelled) {
          setIsCompanyLoading(false)
        }
      }
    }

    fetchCompanyName()

    return () => {
      isCancelled = true
    }
  }, [companyId])

  useEffect(() => {
    const handleCompanyDetailsUpdated = (event: Event) => {
      const customEvent = event as CustomEvent<CompanyDetailsUpdatedEventDetail>
      const detail = customEvent.detail

      if (!detail || detail.companyId !== companyId) {
        return
      }

      setCompanyName(detail.name)
      setCompanyLogoUrl(detail.companyLogoUrl)
      setLogoLoadFailed(false)
    }

    window.addEventListener(COMPANY_DETAILS_UPDATED_EVENT, handleCompanyDetailsUpdated)
    return () => {
      window.removeEventListener(COMPANY_DETAILS_UPDATED_EVENT, handleCompanyDetailsUpdated)
    }
  }, [companyId])

  const handleNavClick = (href: string, closeMobile?: boolean) => {
    if (href === pathname) {
      if (closeMobile) setMobileMenuOpen(false)
      return
    }
    if (closeMobile) setMobileMenuOpen(false)
    startTransition(() => {
      router.push(href)
    })
  }

  const navItemsForUser = NAV_ITEMS.filter((item) => {
    if (isUserLoading) return false
    if (item.path === "/staff-management" && !staffManagementNavVisible) return false
    if (item.path === "/settings" && !propertySettingsNavVisible) return false
    if (!operationsModulesNavVisible && OPERATIONS_MODULE_PATHS.has(item.path)) return false
    if (item.path === "/payments" && !financialNavVisible) return false
    if (item.path === "/housekeeping" && !housekeepingNavVisible) return false
    if (item.path === "/maintenance" && !maintenanceNavVisible) return false
    return true
  })

  const handleLogout = async () => {
    const supabase = createClient()
    try {
      const { data: sessionData } = await supabase.auth.getSession()
      const token = sessionData.session?.access_token
      if (token) {
        await fetch("/api/v1/activity/record-logout", {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        })
      }
    } catch {
      /* audit is best-effort; do not block logout */
    }
    await supabase.auth.signOut()
    window.location.href = "/login"
  }

  return (
